def execute_weekly_refresh():
    with st.status('Verifica aggiornamento WEEKLY dei 200 titoli', expanded=True) as status:
        bar=st.progress(0,text='Controllo archivi locali dei 200 titoli')
        cutoff, yahoo_seconds, needs_calculation=update_weekly_prices(bar)
        if needs_calculation:
            bar.progress(.44,text=f'Dati verificati in {yahoo_seconds:.1f}s · PHASE e V160')
            recalculate(bar)
            target_bar=st.progress(0,text='Target analisti · aggiornamento parallelo')
            target_seconds, live_targets=refresh_targets(target_bar)
            target_bar.empty()
            status.update(label=f'WEEKLY completato · {cutoff:%d/%m/%Y} · target Yahoo {live_targets}/200 ({target_seconds:.1f}s)',state='complete',expanded=False)
        else:
            bar.progress(1.0,text='Nessuna nuova settimana · calcoli scientifici già disponibili')
            status.update(label=f'WEEKLY già aggiornato al {cutoff:%d/%m/%Y} · controllo {yahoo_seconds:.1f}s · nessun download',state='complete',expanded=False)
    return cutoff

